<script setup lang="ts">import { ref,watch } from 'vue';import { get } from '../api';import { useRouter } from 'vue-router';const router=useRouter(),q=ref(''),data=ref<any>();let timer:number;watch(q,()=>{clearTimeout(timer);timer=window.setTimeout(async()=>{data.value=q.value.trim()?await get(`/search?q=${encodeURIComponent(q.value)}`):undefined},250)})</script><template><div><h1 class="title">搜索</h1><input v-model="q" class="input" style="height:64px;width:100%;font-size:24px;margin-top:22px" autofocus placeholder="项目名称、编号、客户或文件…"/><template v-if="data"><section style="margin-top:34px"><h2 class="section-title">项目 / {{data.projects.length}}</h2><div class="list"><div v-for="p in data.projects" class="list-row" @click="router.push(`/projects/${p.id}`)"><b>{{p.name}}</b><span class="subtitle">{{p.status==='COMPLETED'?'已完成':'在办'}} · {{p.businessYear}}</span><span class="arrow">→</span></div></div></section><section style="margin-top:34px"><h2 class="section-title">文件 / {{data.documents.length}}</h2><div class="list"><div v-for="d in data.documents" class="list-row"><b>{{d.originalName}}</b><span class="subtitle">{{d.project}} · {{d.title}}</span><span class="arrow">→</span></div></div></section><p v-if="!data.projects.length&&!data.documents.length" class="subtitle" style="margin-top:32px">没有找到“{{q}}”。试试客户名、项目编号或年份。</p></template></div></template>
